quests[40234] = { id = 40234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood Queen's Court: General Volroth" }
quests[40235] = { id = 40235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dominanzfirlefanz", description = "Die Knalltüten in Hochfels kapier'n nich', dass sie auf'm absteigenden Ast sind. Ich für meinen Teil werd' abstaub'n, solang's was zum Abstaub'n gibt. Je schneller Ihr mir 'n paar Apexiskristalle bringt, desto schneller kann ich mich hier aus'm Staub machen. Ich hab' 'ne ziemlich genaue Vorstellung, wie viele ich brauche.", sourceObjective = "Kluk'kluk möchte, dass Ihr ihm 14958 Apexiskristalle bringt.", progress = "Ich spür' die Macht der Kristalle! Ja, gebt sie her!", completion = "Na endlich! Heute verschwind' ich von hier!\n\nFalls nich', werd' ich mehr davon brauch'n. Neuer Versuch und so.", sourceObjectiveStatus = "unverified-source-field" }
quests[40236] = { id = 40236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerndes Licht", description = "Es ist ein Wunder, dass Ihr überleben konntet, {name}. Und in tiefer Trauer muss ich Euch mitteilen, dass Großmeister Hight nicht so viel Glück hatte. Sein Geist hat nun Ruhe inmitten seiner Ahnen gefunden.\n\nJetzt benötigen wir einen neuen Anführer für unseren Orden, unseren verheerten Tempel. Ich habe mit allen anderen Meistern gesprochen und wir sind uns in dieser Sache einig.\n\nWir haben entschieden, dass Ihr <unser neuer Anführer/unsere neue Anführerin> sein sollt, {name}. Ihr verfügt über unermessliche Stärke, Weisheit, Tapferkeit und Freundlichkeit.\n\nBegleitet uns zum Tempel, damit wir die Entscheidung bekannt geben können.", sourceObjective = "Begleitet Jang den Fürchterlichen und wartet auf die Ankündigung des Meisters.", completion = "Herzlichen Glückwunsch, Großmeister {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[40237] = { id = 40237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeit, Arbeit? Nich' mit uns!", description = "Es reicht! Die Arbeitsbedingungen in der Gießerei sind untragbar. Flammen und Inferno hier, Ogron und Feuerelementar da und dann diese Abenteurer, die hier ständig ein Fass aufmachen! Aber vor allem die Hitze – immer diese Hitze.\n\nNein, Schluss. Aus. Ende! Die Jungs und ich streiken jetzt, aber wir brauchen ein paar Muskeln zu unserem Schutz und der einzige Haudrauf aus Hochfels, der den Job annimmt, will in Apexiskristallen bezahlt werden.", sourceObjective = "Bringt 20000 Apexiskristalle zum Deserteur der Gießerei.", progress = "Gut, dass Ihr Mar'gok ausgeschaltet habt. So viele qualifizierte Schädelquetscher, die neue Arbeit suchen... Ogerwachen sind doch immer noch die besten, findet Ihr nicht?", completion = "Ich würde mich ja bedanken, aber ich bin mir ziemlich sicher, dass wir Euch mit dem Streik einen größeren Gefallen tun als uns. Daher: Gern geschehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40238] = { id = 40238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausame Gleichung", description = "Als wir abgestürzt sind, haben sie schon auf uns gewartet. Uns ist gerade noch gelungen, unseren kleinen Außenposten aufzubauen.\n\nSogar jetzt missbrauchen sie die Seelen unserer Gefallenen, um ihre Angriffe zu verstärken.\n\nVernichtet ihre Seelentresore. Befreit unsere Kameraden, damit sie sich dem Licht anschließen können.\n\nWenn Ihr das erledigt habt, sucht Ihr auf dem Schlachtfeld nach Y'mera. Sie ist leider verschollen, aber ich bin mir sicher, dass sie nicht gefallen ist.", sourceObjective = "Zerstört die drei Seelentresore auf den Zertrümmerten Feldern.", completion = "Gut gemacht. Sie werden bald zurückkehren, aber diesen Vorsprung können wir jetzt nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40240] = { id = 40240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looted Blacksmith Defender's Cache" }
quests[40241] = { id = 40241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bande der Schlacht", description = "Mögt Ihr Haustiere, {name}? Die sind so niedlich!\n\nWas ich aber wirklich gern hätte, sind mehr Sachen, mit denen ich mit ihnen spielen kann.\n\nIch bin sicher, dass Serr'ah drüben bei der Magischen Menagerie ein paar Ideen für spaßige Spielzeuge hat. Ihr solltet Euch mal mit ihr unterhalten!", sourceObjective = "Sprecht mit Serr'ah beim Laden der Magischen Menagerie. Dann kehrt zu Namha zurück.", completion = "Oh, das sind gute Ideen! Lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40242] = { id = 40242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mellok, Son of Torok" }
quests[40243] = { id = 40243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zertrümmert die Waffenständer." }
quests[40244] = { id = 40244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verdächtiges Kostüm", description = "Als wir auf Jagd an der Küste waren, ist uns ein komischer Typ im Kostüm über den Weg gelaufen. Er sagte, er wolle sich so unter die Murlocs mischen... aber ich glaube, er hat nicht mehr alle Tassen im Schrank.\n\nAls wir uns auf den Weg zurück ins Lager gemacht haben, ist jemand zurückgeblieben, um ihn im Auge zu behalten. Könntet Ihr dort mal nachsehen?\n\nTamara da drüben kann Euch hinbringen.", sourceObjective = "Sprecht mit Tamara und fliegt zur Schiffbruchgrotte.", completion = "Hallo, Abenteurer! Seid Ihr hier, um mir und Murky zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[40245] = { id = 40245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looted Tailoring Defender's Cache" }
quests[40246] = { id = 40246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looted Leatherworking Defender's Cache" }
quests[40247] = { id = 40247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gefallen", description = "Caria Teufelsseele war eine unserer Besten... bevor sie dem schändlichen Werben der Legion nachgab.\n\nIhre persönlichen Waffen sind die Kriegsklingen der Aldrachi, die seelenzerfetzenden Klingen des größten Champions dieses uralten Volkes, der sich nur Sargeras selbst geschlagen geben musste.\n\nWir haben einen Suchtrupp entsandt, um Caria aufzuspüren, aber wir haben schon länger nichts mehr von ihnen gehört. Jace ist fast fertig mit der Reparatur eines Legionskommunikators, mit dem man Kontakt zu ihnen aufnehmen kann. Es fehlt nur noch eine Energiequelle.\n\nKönntet Ihr vielleicht Khadgar um Hilfe bitten? Wir haben nicht viele Freunde auf dieser Welt.", sourceObjective = "Fragt Khadgar nach einer Energiequelle für den Legionskommunikator.", completion = "Es ist schön, Euch wiederzusehen. Wenn ich Euch irgendwie dabei helfen kann, die Legion zu bekämpfen, lasst es mich einfach wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40249] = { id = 40249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache wird unser sein", description = "Wir werden es nicht schaffen, unsere Truppen in die Nähe der Verheerten Küste zu bringen, ohne abgeschossen zu werden.\n\nIch denke, dass Ihr diese Operation allein durchführen solltet. Niemand von uns ist so kampferfahren wie Ihr.\n\nRettet nach Möglichkeit Allari und ihre Männer, aber erbeutet um jeden Preis die Kriegsklingen der Aldrachi, denn diese Klingen sind kriegsentscheidender als das Fußvolk.", sourceObjective = "Nehmt Caria Teufelsseele die Kriegsklingen der Aldrachi ab.", completion = "Was ist mit den anderen? Sind sie...?\n\nIch verstehe. Sie haben ihr Leben nicht umsonst geopfert. Die Kriegsklingen werden ganz sicher den Ausgang des Krieges entscheiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40250] = { id = 40250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suramar - Demon Hunter Daily - Choice Reward Summary - 1" }
quests[40251] = { id = 40251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Kethrazor" }
quests[40252] = { id = 40252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormheim - Adventure Mode - Leystone Slab Tracking Quest" }
quests[40253] = { id = 40253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet Gul'dan auf!", description = "Nach seinem Tod im Schwarzen Tempel brachten wir Illidans leblose Hülle hierher, wo sie bis ans Ende der Zeit ruhen sollte.\n\nGul'dan konnte unsere Verteidigung durchbrechen und versucht nun, den Körper des Verräters an sich zu reißen.\n\nSelbst im Tod kann Illidans Körper der Legion von Nutzen sein. Gul'dan DARF ihn nicht bekommen.", sourceObjective = "Betretet den Kerker des Verräters. Tötet dort Zermalmer und Hammer und beansprucht ihre Teufelskraft.", completion = "Ausgezeichnet. Ihr habt diesen Schlägern die Kraft rauben können. Seht nur, wie stark Ihr jetzt seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[40254] = { id = 40254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stählende Flammen", description = "Der gefürchtete Dämon Immolanth eroberte mit einer Armee der Legion eine entfernte Nexuswelt.\n\nDie Wächter konnten ihn in Ketten legen und in der Kammer zu unserer Linken einkerkern. Noch ist er gefangen, doch nicht für ewig.\n\nDie Macht dieses Dämons wäre wohl jedem Dämonenjäger einen Kampf wert. Wer auch immer ihn besiegen kann, erhält unvorstellbare Macht.\n\nIch denke, Ihr seid dieser Aufgabe gewachsen, {name}.", sourceObjective = "Tötet Immolanth und beansprucht seine Macht.", completion = "Ja... seht Euch an... Ihr pulsiert geradezu vor neuer Macht und neuem Wissen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40255] = { id = 40255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Freiheit ist zum Greifen nah", description = "Unsere übrigen Überlebenden haben sich bis in die letzte Kammer vorgekämpft.\n\nNun steht nur noch einer zwischen uns und dem Ausgang des Verlieses – der Anführer der dämonischen Invasionstruppen, Bastillax.\n\nTötet ihn, beansprucht seine Macht und befreit uns.", sourceObjective = "Tötet Bastillax und beansprucht seine Macht.", completion = "Wir sind aus dem Verlies entkommen, doch unser Werk ist noch nicht vollbracht.\n\nDer Angriff der Legion auf diese Welt hat gerade erst begonnen.\n\nWenn Azeroth das überstehen soll, müssen wir uns wohl mit diesem... Erzmagier Khadgar verbünden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40256] = { id = 40256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Freiheit ist zum Greifen nah", description = "Unsere übrigen Überlebenden haben sich bis in die letzte Kammer vorgekämpft.\n\nNun steht nur noch einer zwischen uns und dem Ausgang des Verlieses – der Anführer der dämonischen Invasionstruppen, Bastillax.\n\nTötet ihn, beansprucht seine Macht und befreit uns.", sourceObjective = "Tötet Bastillax und beansprucht seine Macht.", completion = "Wir sind aus dem Verlies entkommen, doch unser Werk ist noch nicht vollbracht.\n\nDer Angriff der Legion auf diese Welt hat gerade erst begonnen.\n\nWenn Azeroth das überstehen soll, müssen wir uns wohl mit diesem... Erzmagier Khadgar verbünden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40257] = { id = 40257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenjägerauswahl 1" }
