quests[40261] = { id = 40261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenjägerauswahl 3" }
quests[40265] = { id = 40265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch von Magie", description = "Ich war immer stolz auf mein Zuhause... und meine Verzauberungen. Jetzt ist das alles hinfällig.\n\nIch spüre, dass Ihr <ein mächtiger Verzauberer/eine mächtige Verzauberin> seid, {name}. Wenn Ihr etwas magischen Staub über meine ehemals verzauberten Besitztümer streut, könnt Ihr sie vielleicht wieder zum Leben erwecken.", sourceObjective = "Streut Arkhana auf inaktive Gegenstände in Tigrids Haus.", progress = "Allein die Gegenwart eines so mächtigen Verzauberers versieht mein Haus mit einem neuen Lebensfunken.", completion = "Ich freue mich sehr, dass Ihr meine geliebten Verzauberungen wieder zum Leben erweckt habt.\n\nFrüher habe ich noch ganz andere Dinge als Salontricks beherrscht. Aber dann wurde mir die Quelle meiner Kraft gestohlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40266] = { id = 40266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gedankenverlorene Ratgeber", description = "Wo Ihr schon mal hier seid, könnt Ihr mir auch helfen. Ich muss einen Trank herstellen, der die Dinge wieder geraderückt.\n\nBis diese Aufgabe erledigt ist, muss ich meine Kräfte schonen, sonst werde ich wie einer dieser armen Kerle, die am Kopfsteinpflaster herumkratzen. Ihr könnt Euch damit auch ein paar Münzen verdienen, denn ich habe für sie in nächster Zeit keinerlei Verwendung.\n\nDie Harpyien hier werden geradezu magisch von Klippendorn angezogen. Genau das hat sie auch in erster Linie nach Tel'anor gelockt. \n\nIhr findet draußen vor dem Gebäude jede Menge davon.", sourceObjective = "Sammelt 8 Zweige Klippendorn.", progress = "<Thaedris scheint ganz in Gedanken verloren, während er in Richtung Suramar blickt.>", completion = "<Thaedris schreckt aus seinen Gedanken hoch, als Ihr Euch nähert.>\n\nDas wird reichen, {race}.\n\nKlippendorn enthält ein tödliches Gift und ist damit perfekt für meine Zwecke.", sourceObjectiveStatus = "unverified-source-field" }
quests[40267] = { id = 40267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unerwartete Nachricht", description = "Ah, Felo'melorn. Ich bin mit dieser Waffe vertraut.\n\nSchon seit einer Ewigkeit hat der Rat von Tirisfal versucht, dieses Schwert zurückzuerlangen. In den falschen Händen könnte seine Macht über die Urgewalt des Feuers schrecklichen Schaden anrichten.\n\nAber zum Glück hat Erzmagierin Modera, eine Verbündete von mir, kürzlich einige Informationen über dieses Artefakt in Erfahrung bringen können. Dieser Kristall hier beinhaltet eine Nachricht von ihr.\n\nIch schlage vor, dass Ihr dort mit Eurer Suche beginnt. Das Portal da drüben bringt Euch zurück in die Stadt.", sourceObjective = "Empfangt mithilfe des leuchtenden Resonanzkristalls die Nachricht von Erzmagierin Modera.", completion = "Ich bin froh, dass Ihr zu mir gekommen seid, {name}.\n\nIch habe Informationen über das Objekt, mit dem wir diesen Krieg für uns entscheiden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[40270] = { id = 40270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Abbitte", description = "Felo'melorn, die Runenklinge der Könige von Quel'Thalas... Man sagt, dass sie die elementare Kraft des Feuers birgt und selbst dem legendären Frostgram widerstehen konnte, nachdem Kael'thas sie verstärkt hatte.\n\nWir glaubten, dass dieses Schwert mit dem Tod von Kael'thas verloren gegangen sei, aber ein Verbündeter von mir hat Hinweise darauf erhalten, wo es sich befinden könnte.\n\nWir müssen dieser Sache nachgehen, denn mit Felo'melorn in Euren Händen könnten wir die Legion das Fürchten lehren!\n\nAh, unsere Begleitung ist eingetroffen.", sourceObjective = "Sprecht mit dem Verbündeten von Erzmagierin Modera am Dalarankrater im Vorgebirge des Hügellands.", completion = "Unsere nächste Reise führt uns in die Eiskronenzitadelle, {name}.\n\nDort, mitten im Herzen der Geißel, werden wir Felo'melorn finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40272] = { id = 40272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Village - Medium Treasure 001 - twh" }
quests[40273] = { id = 40273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah -  Temple of Elune - Medium Treasure 001 - bic" }
quests[40274] = { id = 40274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 010" }
quests[40276] = { id = 40276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mahlstrom ruft", description = "Könnt Ihr es spüren, <Schamane/Schamanin>? Hier, im Herzen von Azeroth, wo Erde, Wind und Wellen aufeinanderprallen, scheint man mit der Welt selbst sprechen zu können.\n\nEuer Artefakt verfügt über große Macht und noch größeres Potenzial. Bringt es nach dort unten zum uralten Elementaraltar, gleich neben dem wirbelnden Mahlstrom. Dort könnt Ihr mit Azeroth kommunizieren und Euer Artefakt mit noch mächtigeren Fähigkeiten ausstatten. Macht Euch auf und zeigt mir dann, was Ihr gelernt habt!", sourceObjective = "Begebt Euch zum uralten Elementaraltar, um Euer Artefakt mit neuer Macht zu erfüllen.", completion = "Ich spüre, dass Eure Arbeit hier gerade erst begonnen hat. Je vertrauter Ihr mit Eurem Artefakt werdet, desto weiter könnt Ihr seine Kräfte verstärken.\n\nDie anderen beobachten Euch aufmerksam. Ihr seid bereits zu einem Symbol der Hoffnung in unserem Kampf gegen die Legion geworden!", sourceObjectiveStatus = "unverified-source-field" }
quests[40277] = { id = 40277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfnacht: Tiffany Nelson" }
quests[40278] = { id = 40278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Geheiß meines Tiers" }
quests[40279] = { id = 40279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training mit Durian", description = "Zeigt mir, dass Ihr wirklich das Vertrauen Eurer Begleiter gewonnen habt.", sourceObjective = "Besiegt Durian Starkfrucht in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[40280] = { id = 40280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training mit Bredda", sourceObjective = "Besiegt Bredda Zarthaut in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[40282] = { id = 40282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Wilderer, kleine Tiere", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[40296] = { id = 40296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Corridor" }
quests[40297] = { id = 40297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lyana Düstergram", description = "<Vor Euch schwebt eine gefangene Dämonenjägerin in Stasis. Ihre Seele wird langsam in den Erntekristall hineingesogen.>\n\n<Ihr müsst den Seelenernter vernichten, wenn Ihr sie aus der Stasis befreien wollt.>", sourceObjective = "Vernichtet den Seelenernter.", completion = "Mein Name ist Lyana. Und wie lautet Eurer, {class}?\n\nDanke, dass Ihr mich befreit habt.\n\nIch weiß gar nicht, wie lange ich gefangen gehalten wurde... Aber ich spüre, dass sich eine große Anzahl Dämonen in der Nähe befindet.\n\nEs liegt noch viel Arbeit vor uns beiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40298] = { id = 40298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfnacht: Sir Galveston" }
quests[40299] = { id = 40299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfnacht: Bodhi Sonnenreiter" }
quests[40300] = { id = 40300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeuge des Handwerks", description = "Ich bin oft hierhergekommen, bevor die Barriere errichtet wurde. Während der regierende Rat und die Großmagistrix über politische Dinge diskutierten, habe ich die Wärter dabei beobachtet, wie sie ihre Rituale abgehalten und die Totenehrungen vorgenommen haben.\n\nIch möchte den Geistern hier ein letztes Mal die Ehre erweisen und bin unterwegs zu den Gräbern. Falls etwas von den heiligen Ölen, den Leichentüchern und dem Räucherwerk all die Jahre überdauert hat, dann bringt es zu mir.", sourceObjective = "Besorgt Grabbeigaben für Thaedris.", progress = "Habt Ihr irgendetwas finden können?", completion = "Ein wirklich eindrucksvoller Beleg unserer Konservierungstechniken. Ich hatte schon längst die Hoffnung verloren, dass etwas davon die Plünderungen und die lange Zeit überstanden haben könnte.\n\nDie Ahnen werden darüber sehr erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[40301] = { id = 40301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Phalanx Captain" }
quests[40302] = { id = 40302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Prospecting 01" }
