quests[40305] = { id = 40305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barracks Drop 01 Tracking Event" }
quests[40306] = { id = 40306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Kapitel", description = "Für die nächste Etappe meiner Reise benötige ich einen Folianten. Aber ich bin noch nicht so weit, tatenlos zuzusehen, wie hier alles immer weiter verwahrlost.\n\nIch werde hier wenigstens die Denkmäler entstauben, während Ihr loszieht und mir den Folianten besorgt. Er nennt sich Encyclopaedia Botanica und Ihr findet ihn in der Bibliothek nahe des Hauptplatzes.", sourceObjective = "Sucht nach der Encyclopaedia Botanica.", progress = "Habt Ihr den Folianten, {race}?", completion = "Hm, wenn Ihr mir schon bei dieser Aufgabe helft, sollte ich mir vielleicht besser Euren Namen merken.\n\n<Thaedris greift in das Buch und zieht eine unbekannte, getrocknete Pflanze heraus.>\n\nDanke, dass Ihr mir eine weitere Zutat besorgt habt. Ich bin Euch sehr dankbar für Eure Hilfe... {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40307] = { id = 40307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glevierende Umstände", description = "Ich bin mit dem Auftrag hierhergekommen, den Dämoneneredar Azoran zu töten, wurde aber auf dieser Mission von meiner Teufelsfledermaus heruntergeschossen und gefangen genommen.\n\nIch will ganz offen mit Euch sprechen, {name}. Azoran plant, das Kommandoschiff der Brennenden Legion einzusetzen, um Dalaran zu vernichten.\n\nUm ihn aufzuhalten, benötige ich meine Kriegsgleven, die ich bei meinem Sturz aus der Luft verloren habe. Ich würde sie mir ja selbst zurückholen, aber ich bin nach meiner Gefangenschaft noch zu schwach.\n\nSucht bitte nach den Kriegsgleven auf der nördlichen Seite des Kraters, wo ich abgeschossen wurde.", sourceObjective = "Holt Lyana Düstergrams Gleven zurück.", progress = "Habt Ihr meine Gleven, {race}?", completion = "Ich danke Euch. Jetzt, wo meine Kriegsgleven wieder da sind, werde ich die Teufelsseelenbastion in Schutt und Asche legen.\n\nMein Zorn ist unendlich und meine Rache schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[40308] = { id = 40308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruchstücke der Erinnerung", description = "<Die wunderschöne Elfenurne wurde achtlos auf dem Boden zerschmettert. Sie wurde offensichtlich nicht zärtlich behandelt, hat aber keinen Schaden durch die Krallen der Harpyien genommen.>\n\n<Ihr findet eine Spur von Scherben, die in Richtung der Höhle führt. Dort müssen sich die Verantwortlichen aufhalten. Thaedris würde sich sicher freuen, die Relikte gut erhalten zurückzubekommen.>", sourceObjective = "Bergt 15 Andenken an Tel'anor.", progress = "Was habt Ihr denn da?", completion = "Diese Relikte sind Erinnerungen und Andenken an die früheren Leben jener, die hier begraben liegen. Sie möchten, dass man sich an sie erinnert, und diese Opfergaben sorgen dafür, dass ihnen ewiger Friede zuteilwird.\n\nDie Geister der Gefallenen finden jetzt wieder ihre Ruhe. Ich danke Euch vielmals.", sourceObjectiveStatus = "unverified-source-field" }
quests[40310] = { id = 40310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffbrüchiger Gefangener", description = "Ich habe mein Leben damit zugebracht, in den Kämpfen anderer Leute das Haustier zu geben. Jetzt ist es an mir, ein Tierzähmer zu sein! Und das Beste ist: Jetzt, da ich tot bin, kann ich das bis in alle Ewigkeit tun!", sourceObjective = "Besiegt den schiffbrüchigen Gefangenen in einem Haustierkampf.", completion = "Ich werde besser werden. Ich habe die ganze Ewigkeit, um zu üben!", sourceObjectiveStatus = "unverified-source-field" }
quests[40313] = { id = 40313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barracks Drop 02 Tracking Event" }
quests[40314] = { id = 40314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Treasure Cache" }
quests[40315] = { id = 40315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endstation", description = "Ich kann Suramar nicht mehr als mein Zuhause bezeichnen und ich weigere mich, eine verdorrte Monstrosität zu werden. Es gibt keinen Ort mehr, an den ich gehöre, versteht Ihr?\n\nWir benötigen nur noch eine letzte Zutat für das Elixier. Ihr werdet mir doch helfen, oder?", sourceObjective = "Sprecht mit Thaedris auf der oberen Ebene von Tel'anor.", completion = "Eure Argumente sind nicht unschlüssig, {name}. Aber ich bleibe bei meiner Meinung.", sourceObjectiveStatus = "unverified-source-field" }
quests[40316] = { id = 40316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreischende Felsen" }
quests[40317] = { id = 40317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baum zerstört" }
quests[40319] = { id = 40319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Zutat", description = "Der Trank ist fertig, {name}. Bald wird unsere Reise ein Ende finden. Es gibt aber noch eine Sache, die Ihr für mich tun müsstet, bevor Ihr Eure Belohnung bekommt.\n\nDer Bogen meiner Frau wurde hier verwahrt, aber ich kann ihn einfach nicht mehr finden. Er birgt besonders mächtige Magie.\n\nIch fürchte, dass einer der ruhelosen Geister ihn sich gegriffen hat. Allerdings braucht es immense Kräfte, um so einen mächtigen Gegenstand aufnehmen zu können. Passt bitte gut auf Euch auf.", sourceObjective = "Sucht nach Lataras Bogen.", progress = "Was war das? Ich habe eine vertraute Stimme gehört... aber das kann nicht sein...", completion = "Ihr habt Latara gesehen? Was ist geschehen?\n\n... Ich verstehe. Es tut mir so leid, dass ich dich enttäuscht habe, meine Liebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[40320] = { id = 40320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsbrüder", description = "Ihr seid also <dieser Außenseiter, von dem/diese Außenseiterin> von der; Toryl gesprochen hat? Vielleicht könnt Ihr mir helfen.\n\nAls ich aufbrach, um nach Throndyr zu suchen, war ich nicht allein. Drei Throndyr treu ergebene Vrykul waren bei mir. Aber wie Ihr seht, ist hier niemand mehr außer mir.\n\nFindet meine Leute, {name}.\n\nIch hoffe, dass sie nicht das gleiche Schicksal wie Throndyr ereilt hat.", sourceObjective = "Sucht nach Katarine, Fjolrik und Stokalfr in der Muddeltiefenhöhle.", progress = "Ich muss wissen, was mit meinen Leuten geschehen ist.", completion = "Meine Leute sind sicher. Dann wollen wir uns jetzt um diese Schlangen kümmern!", sourceObjectiveStatus = "unverified-source-field" }
quests[40321] = { id = 40321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federsangs Erlösung", description = "Ich muss gestehen, dass ich nicht ganz ehrlich zu Euch war, {name}. Ich wollte den Trank trinken, um mich wieder mit meiner Frau zu vereinen.\n\nUnd selbst sie wurde in ihrer Ruhe gestört... Ich darf sie nicht noch einmal enttäuschen. Ich muss leben und mich dem aufziehenden Sturm entgegenstellen, um mich ihrer wieder würdig zu erweisen.\n\nKommt, lasst uns diese Harpyienmatriarchin ausschalten und Tel'anor zu früherem Ruhm zurückführen. Wir dürfen doch dieses hübsche Gift nicht verschwenden, oder?", sourceObjective = "Tötet die Matriarchin der Klippengreifer.", progress = "Es wird seine Zeit brauchen, doch Tel'anor wird wieder aufblühen. Das schwöre ich bei meinem Leben.", completion = "Habt Dank, {name}. Ihr habt mir meine Bestimmung aufgezeigt und meinem Leben wieder einen Sinn verliehen. Zusammen werden wir Suramar retten und für die Sünden meines Volks Sühne leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[40324] = { id = 40324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Zwiesprache", description = "Alle von Kel'danaths Experimenten, eine Verbindung zu den Verdorrten herzustellen, waren gescheitert. Durch einige von ihnen wurden sie sogar noch gefährlicher.\n\nBis er Theryn fand.\n\nSeine arkane Essenz, die wahre Seele der Shal'dorei, war von etwas Besonderem berührt worden. Aber von was genau?\n\nIndem ich meine arkane Essenz mit der von Theryn verwebe, kann ich eine empathische Verbindung herstellen. Diese Verbindung wird uns allen seine Seele offenbaren... oder das, was davon übrig ist.\n\nUm zu beginnen, müssen wir ihn lediglich mit Mana füttern... viel Mana.", sourceObjective = "Nährt Theryn mit 300 uraltem Mana.", progress = "Gebt Theryn so viel davon wie möglich.", completion = "Gut. Dann wollen wir mal sehen, was wir von ihm lernen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[40325] = { id = 40325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Szenen einer Erinnerung", description = "Theryn ist Sklave seines eigenen Geistes. Was auch immer wir darin finden, könnte schwierig zu kontrollieren sein.\n\nIch werde Eure Hilfe benötigen, um mich durch seine Visionen zu arbeiten, also seid auf alles vorbereitet.\n\nMit etwas Glück finden wir heraus, was Theryn so besonders macht. Und... ob noch etwas von der Person übrig ist, die er einst war.", sourceObjective = "Helft Thalyssra, die arkane Zwiesprache mit Theryn abzuschließen.", completion = "Die Verdorrten... Sie quält nicht nur der ewige Durst nach dem Nachtbrunnen, auch ihre eigenen Erinnerungen sind die reinste Folter für sie.\n\nWahrlich ein Schicksal schlimmer als der Tod...", sourceObjectiveStatus = "unverified-source-field" }
quests[40326] = { id = 40326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinzelte Erinnerungen", description = "<Eure Finger streichen über die eleganten Zeichen auf der Seite, während eine Stimme Euch im Geiste die Worte diktiert.\n\nDie Nachtgeborenen haben offenbar sogar einfache Notizen zu einer Zauberkunst perfektioniert.\n\nEindeutig war hier Arkanist Kel'danath am Werk. Es müssen noch mehr seiner Notizen verstreut sein.>", sourceObjective = "Betrachtet 6 Seiten von Kel'danaths Notizen.", completion = "<Eine Tasche mit zahllosen Seiten voll technischer Notizen. Ihr blättert in ihnen und findet Kel'danaths letzten Eintrag.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40327] = { id = 40327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Metall wird auf die Probe gestellt", description = "Also schön, wenn wir hier rauskommen wollen, müssen wir einen Weg um die Naga und die Meeresriesen herum finden.\n\nDie Naga werden wahrscheinlich kein großes Problem für jemanden mit Euren Fähigkeiten darstellen, aber diese Meeresriesen sind unglaublich stark.\n\nBringt mich nur sicher aus dieser Höhle heraus. Den Weg nach Hause finde ich dann allein.\n\nHoffentlich wird diese Rüstung, die Celea für mich angefertigt hat, mich so lange schützen, bis das hier vorbei ist.", sourceObjective = "Bringt Taldranis in Sicherheit.", completion = "Er ist sicher hinausgekommen? Elune sei gelobt... und Ihr, {name}.\n\nEure Heldentaten fördern mein Vertrauen in Euch, und ich werde Euch ausbilden, {name}. Hier sind einige effizientere Methoden, um Eure Rüstung herzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40328] = { id = 40328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schicksal schlimmer als der Tod", description = "Wenn die Brennende Legion Gefangene nimmt, ist dies kein Akt der Barmherzigkeit.\n\nDer Tod ist die Vernichtung des sterblichen Körpers... doch wenn die Legion Euch gefangen nimmt, dann wird sie Eure Seele zerstören.\n\nDie Brennende Legion opfert Seelen, um ihre dämonischen Kriegsmaschinen anzutreiben. Die gestohlenen Seelen werden in der Seelenmaschine gesammelt und aufbewahrt.\n\nZahllose Opfer sind in der Seelenmaschine zugrunde gegangen, doch noch könnt Ihr die verbleibenden vielleicht retten.\n\nBeeilt Euch und befreit sie, bevor es zu spät ist!", sourceObjective = "Öffnet 8 Käfige der Seelenmaschine.", progress = "Wurden die Käfige der Seelenmaschine geöffnet?", completion = "Die Zerstörung der Seele ist ein viel schlimmeres Schicksal als der Tod. Ihr habt jenen, die Ihr gerettet habt, einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40329] = { id = 40329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Warlords", description = "Ihr habt bewiesen, dass ihr ein Meister eures Fachs seid, doch die Wildnis von Draenor verspeist Meister zum Frühstück. Zeigt, aus welchem Holz ihr wirklich geschnitzt seid und besiegt diese Haustierzähmer: Cymre Leuchtklinge in Gorgrond, Vesharr in den Spitzen von Arak, Tarr den Schrecklichen in Nagrand, Taralune in Talador, Gargra im Frostfeuergrat oder Ashlei im Schattenmondtal. Ihr könnt Euch auch Besuchern Eurer Garnison stellen: Erris der Sammlerin oder Kura Donnerhuf.\n\nEin Sieg über sie, wird Eure Überlegenheit in Draenor beweisen.", sourceObjective = "Besiegt fünf Kampfhaustiertrainer in Draenor.", completion = "Kein Haustierkämpfer aus Draenor kann Euch das Wasser reichen. Nun seid Ihr bestens gewappnet, um anderen Helden wie Euch die Stirn zu bieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[40331] = { id = 40331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Biss der Sashj'tar", description = "Wenn ich im Kampf gegen die Naga an Throndyrs Seite gewesen wäre, würde er vielleicht noch leben.\n\nDiese Schlangen werden den Tag noch bereuen, an dem sie aus ihrem nassen Loch gekrochen kamen!\n\nEs reicht mir nicht, sie nur zu töten. Nein! Ich werde Throndyr mit einer Halskette aus Nagazähnen ehren!", sourceObjective = "Sammelt 8 Fangzähne der Sashj'tar in der Azurwindbucht.", progress = "Wir werden sie alle töten!", completion = "Die werde ich zu Ehren Throndyrs tragen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40332] = { id = 40332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer am Strand", description = "Lasst... meinen Körper... nicht... im Schlamm liegen.\n\nSetzt mein Fleisch... in Brand.", sourceObjective = "Sammelt 6 Stücke Treibholz in der Azurwindbucht und errichtet einen Scheiterhaufen für Jarl Throndyr.", progress = "Throndyr hatte einen ehrenhafteren Tod verdient.", completion = "Ehre sei Jarl Throndyr! Möge Eure Seele ihren Platz in den Hallen der Tapferkeit finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40334] = { id = 40334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischers frisches Fläschchen", description = "Wenn Ihr diese Schlangen genauso hasst wie wir, bitte ich Euch, weiter gegen sie zu kämpfen.\n\nDazu werdet Ihr sie jedoch in ihrem nassen Zuhause stellen müssen. Ich sehe keine Kiemen an Euch, also werden wir ein altes Tonikum der Vrykulfischer zusammenmischen müssen.\n\nDie Zutaten gibt es hier in Hülle und Fülle... solange es Euch nichts ausmacht, in Eingeweiden herumzuwühlen.", sourceObjective = "Sammelt 4 Hackschwanzaugäpfel von Hackschwanzbasilisken, eine Schwimmblase der Sashj'tar von den Naga der Sashj'tar und eine Sirenenblutprobe von Naz'jul der Sirene im Azurwindmeerbogen ein.", progress = "Ich werde Euch helfen, die benötigten Dinge zu sammeln.", completion = "<Brandolf mischt die Mixtur zusammen.>\n\nIch habe nie behauptet, dass es gut schmecken würde. Runter damit.", sourceObjectiveStatus = "unverified-source-field" }
quests[40336] = { id = 40336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gezeitenherrin Herr werden", description = "Die Gezeitenherrin hat sich in die Elfenruinen zurückgezogen, um ihre Wunden zu lecken.\n\nIhre Wache wird sie zweifelsohne beschützen. Ihr müsst ihre Verteidigung durchbrechen, wenn Ihr sie bezwingen wollt.\n\nBaut eine Balliste aus Euren geborgenen Teilen und macht ihr ein für alle Mal den Garaus.", sourceObjective = "Baut eine improvisierte Balliste und tötet Gezeitenherrin Sashj'tar in den Ruinen der Sashj'tar.", completion = "Ihr habt es geschafft, {name}. Ihr habt die Gezeitenherrin getötet und Jandvik vor den Sashj'tar gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[40337] = { id = 40337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perplex" }
quests[40338] = { id = 40338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 009" }
quests[40339] = { id = 40339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wächserne Befehlsgewalt", description = "Du nicht reinkommen! Wenn du reinwillst, dann gib anderen Kobolden von Thron der Rumkommandiererei aus Befehle. Dann wir reden. Vielleicht.", sourceObjective = "Setzt Euch auf den Thron der Rumkommandiererei und gebt den Kobolden, die sich Euch nähern, Befehle.", progress = "Was glotzen Stinkkopf so doof?", completion = "Wieso du schon wieder hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[40340] = { id = 40340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alard Schmied Greeting Seen" }
quests[40341] = { id = 40341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thron der Gezeiten: Die Macht Azsharas", description = "Wellensprecherin Adelee konnte Sharas'dal bis zum Thron der Gezeiten im Meeresschlund verfolgen, bevor sie von der Bildfläche verschwand. {name}, wenn wir ihr folgen, werden wir ziemlich sicher in eine Falle tappen.\n\nAber die Elemente stehen uns bei. Die Naga werden nicht mit <einem Schamanen/einer Schamanin> Eures Formats rechnen!\n\nSchwimmt im Meeresschlund nach Nordwesten zum Thron der Gezeiten. Dort werde ich mich Euch anschließen. Lasst uns nach unserer vermissten Schamanin suchen und das Artefakt holen!", sourceObjective = "Reist zum Thron der Gezeiten und holt Sharas'dal.", completion = "Dann waren die Legenden über das Szepter der Gezeiten also wahr, {name}!\n\nEs ist eine große Freude, ein solch mächtiges Artefakt in den Händen des Irdenen Rings zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40342] = { id = 40342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überraschung für die Sashj'tar", description = "Die Naga sind damit beschäftigt, Meeresriesen für Königin Azsharas Schlachten in anderen Ländern zu rekrutieren.\n\nJetzt ist der richtige Zeitpunkt zum Zuschlagen!", sourceObjective = "Tötet 12 Champions der Sashj'tar oder Tiefenhexen der Sashj'tar in der Azurwindbucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40343] = { id = 40343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magni/Eitrigg Meetup Seen" }
quests[40345] = { id = 40345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kerze an beiden Enden entzünden", description = "Warum du schon wieder hier? Musst warten, bis alle Arbeiten erledigt sind, sonst ich nicht durchlassen!\n\nGeh zurück zu Thron der Rumkommandiererei und mach, dass alles fertig wird!", sourceObjective = "Sorgt dafür, dass die Kobolde die Arbeiten zu Ende bringen.", progress = "Du reinkommen, wenn Arbeiten erledigt.", completion = "Was?! Du haben Spezialkerze des Kerzenkönigs!", sourceObjectiveStatus = "unverified-source-field" }
quests[40346] = { id = 40346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geplünderter Proviant", description = "Die Meeresriesen durchsuchen die Schiffswracks nach Schätzen. Wertvolle Dinge, die sich dort finden lassen, wären aber bei den Vrykul besser aufgehoben.", sourceObjective = "Sammelt 8 Kisten mit geplündertem Proviant aus Schiffswracks in der Azurwindbucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40347] = { id = 40347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurbog da Basher" }
quests[40348] = { id = 40348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trübes Wasser", description = "Etwas verdirbt dieses Wasser, {class}.\n\nWir müssen das Wasser läutern, um das Gleichgewicht der Elementarkräfte unterhalb dieser Ruine wiederherzustellen.\n\nDie Magie hier hat die Elementare verwandelt und entstellt, und es ist für jede Heilung zu spät. Befreit diese verderbten Erscheinungen, auf dass sie geläutert wiedergeboren werden können.", sourceObjective = "Tötet 12 manaverderbte Wasserwesen.", completion = "Jetzt, da wir die Verderbnis geläutert haben, können die frischen Wasserelementare gedeihen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40349] = { id = 40349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloses Violettglasgefäß", description = "Dieses Artefakt wurde restauriert und ist nun in bemerkenswert gutem Zustand. Ihr könnt es jetzt im Archäologieladen in Dalaran ausstellen.", sourceObjective = "Stellt das Artefakt zur Schau.", sourceObjectiveStatus = "unverified-source-field" }
