quests[40364] = { id = 40364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blasenbeschwerden", description = "{class}! Die Meeresriesen haben schon die Hälfte von uns gefressen.\n\nWir sind wehrlos in diesen verfluchten Blasen. Ich flehe Euch an, uns hier herauszuholen.\n\nSeid vorsichtig. Die Blasen sind stark. Ihr werdet etwas extrem Scharfes brauchen, um sie zu durchdringen.", sourceObjective = "Sammelt eine Nadelkoralle ein und rettet dann 5 gefangene Vrykul in der Azurwindbucht.", progress = "Schnell, {class}! Diese Meeresriesen haben einen unersättlichen Appetit!", completion = "Es liegt weder Ruhm noch Ehre darin, verdaut zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40368] = { id = 40368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildkröten vonnöten", description = "Ich werde einen Elementarfokus brauchen, um den Ursprung der Verderbnis auszumachen und zu läutern.\n\nDie Schildkröten in dieser Gegend haben Schuppen entwickelt, die die ihnen innewohnende Magie noch weiter fokussieren und verstärken können. Bringt mir einige Schnapperschuppen, dann haben wir dieses Wasser schon bald wieder gereinigt!", sourceObjective = "Sammelt 7 schimmernde Schnapperschuppen.", progress = "Denkt daran, dass die Schuppen für die Verwendung als Fokus intakt sein müssen.", completion = "Damit wird es gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40369] = { id = 40369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Ironbranch" }
quests[40370] = { id = 40370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles ins Reine bringen", description = "Spürt Ihr es auch, {race}? Es ist jetzt so weit, dass wir alles wiedergutmachen können.\n\nWährend Ihr beschäftigt wart, habe ich den alten Elementar aufgespürt, der über diese Gewässer herrscht. Er heißt Azursturzwächter und lebt in den Kanälen von Tel'anor.\n\nNehmt den Ritualfokus, er wird Euch im Kampf nützlich sein.", sourceObjective = "Besiegt die Verderbnis des Azursturzwächters.", completion = "Es ist vollbracht. Ich spüre schon, wie die verderbende Präsenz hinfortgeschwemmt wird.\n\nHabt Dank, {name}. Ihr habt diesem Ort einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40373] = { id = 40373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frischer Wind", description = "{name}, als Anführer der Illidari in Lord Illidans Abwesenheit müsst Ihr für Euch einen Stellvertreter wählen.\n\nKayn oder Altruis? Ihr müsst Euch für einen der beiden entscheiden.\n\nDer Auserwählte wird fortan Euer persönlicher Champion sein und seine Ideologie wird unsere Entscheidungen über die Illidari maßgeblich beeinflussen. Ganz gleich, auf wen die Wahl fällt, unsere Mission bleibt unverändert.\n\nWenn Ihr eine Gedächtnisstütze braucht, was unsere Vergangenheit angeht, so blickt in das Becken des Urteils. Denkt an die Opfer, die uns zu Dämonenjägern gemacht haben. Sprecht mich an, wenn Ihr bereit seid, zu wählen.", sourceObjective = "Wählt zwischen Kayn oder Altruis aus.", progress = "Habt ihr eine Entscheidung getroffen?", completion = "Interessante Wahl. Ich unterstütze Euch, so oder so. Mit diesem Neubeginn werden wir die Illidari wieder erstarken lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40374] = { id = 40374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Direction: Obtained Kayn" }
quests[40375] = { id = 40375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Direction: Obtained Altruis" }
quests[40378] = { id = 40378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftritt der Illidari: Aschenzungen", description = "Lord Illidan hat Euch das Kommando anvertraut. Nun brauchen wir den Rest unserer Illidaritruppen.\n\nVor uns gibt es drei Tore der Brennenden Legion. Aktiviert sie und unsere Illidari können vom Schwarzen Tempel aus zu uns stoßen.\n\nWie die meisten Konstruktionen der Legion werden die Tore mit Seelen angetrieben. Für das erste sollte es bereits reichen, was denkt Ihr? Ebnen wir unseren Truppen der Aschenzungen den Weg.", sourceObjective = "Beschwört Eure Truppen der Aschenzungen, indem Ihr das Legionstor aktiviert.", completion = "Sie sind eben vorbeigekommen. Nicht unsere furchterregendsten Kämpfer, doch sie haben sich früher bereits als nützlich erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40379] = { id = 40379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftritt der Illidari: Naga der Echsennarbe", description = "Das nächste Tor ist unten an der Geschmolzenen Küste. Unsere Truppen der Echsennarbe warten am Schwarzen Tempel auf der anderen Seite.\n\nUnsere Nagaverbündeten wären nicht zwingend meine erste Wahl gewesen, doch sie haben Lord Illidan die Treue geschworen. Wir werden sehen...\n\nWir müssen einen Weg finden, den Toraktivator mit Energie zu versorgen. Er benötigt Seelen, wie die anderen.\n\n<Allari die Seelenfresserin grinst, als Savis das sagt.>", sourceObjective = "Speist den Toraktivator der Legion mit einer Seele und öffnet damit einen Weg für Eure Truppen der Echsennarbe.", completion = "Ein grausames Tagwerk, doch wir haben alle bereits so viel geopfert, um dahin zu gelangen, wo wir jetzt sind.\n\nWir werden ALLES tun, was nötig ist, um die Brennende Legion zu besiegen. Einfach Alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[40380] = { id = 40380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Thondrax" }
quests[40381] = { id = 40381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Darkfiend Assassin" }
quests[40382] = { id = 40382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Jinikki the Puncturer" }
quests[40383] = { id = 40383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Kiranys Duskwhisper" }
quests[40384] = { id = 40384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waidfraus Ruf", description = "Der Adler scheint eine Nachricht für Euch zu haben:\n\n\n\nDie Zeit ist gekommen, gegen die Legion zurückzuschlagen.\n\nTrefft mich sobald wie möglich in den \"Weiten des Jägers\" in Dalaran.\n\n- Emmarel Schattenwächter", sourceObjective = "Sprecht mit Emmarel Schattenwächter in Dalaran.", completion = "Euer Ruf eilt Euch voraus, {name}.\n\nWir haben wichtige Dinge zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40385] = { id = 40385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Speer im Schatten", description = "Vor vielen Jahren hat ein verderbter Nachtsäbler mein Volk gejagt. Unser Häuptling, Dorro Hochberg, zog mit Fangklaue aus, um die Bestie zu jagen, aber er kehrte nie wieder zurück.\n\nMan hat mir Geschichten über einen furchterregenden Nachtsäbler zugetragen, der jetzt durch die Nebel von Sturmheim streift. Mein Bruder und ich glauben, dass es sich um unseren uralten Feind handelt.\n\nDie Waffe muss auch dort sein! Wenn wir die Bestie töten und den Speer zurückerobern können, wird er uns im Kampf gegen die Legion von großem Nutzen sein.", sourceObjective = "Bringt den Schrecken des Hochbergs zur Strecke.", completion = "Dann ist der Fluch des Hochbergs also tot und Fangklaue konnte geborgen werden! Gut gemacht, {name}!\n\nIch trauere um Apata und Wuho. Wir werden sie in den kommenden Auseinandersetzungen schmerzlich vermissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40386] = { id = 40386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Khadgar Arrival" }
quests[40388] = { id = 40388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hulns Krieg - Schattensang", description = "Unten auf dem Schlachtfeld führt jetzt jemand das Kommando, den Ihr meines Wissens kennt.\n\nJarod Schattensang hält große Stücke auf Euch und wünscht, dass Ihr an seiner Seite kämpft.\n\nEr will diesen Kampf endgültig beenden.", sourceObjective = "Trefft Euch mit Jarod Schattensang auf dem Schlachtfeld.", completion = "Ich freue mich sehr, Euch zu sehen, treuer Verbündeter.", sourceObjectiveStatus = "unverified-source-field" }
quests[40389] = { id = 40389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure - Skyhorn Kite Created" }
quests[40390] = { id = 40390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligter Boden" }
quests[40391] = { id = 40391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mich zu Eurem Anführer", description = "Ich bin sehr froh, dass Ihr da seid, {name}.\n\nDieser... Khadgar, der Erzmagier, der meine Nachricht gefunden hat, hat ein Treffen einberufen.\n\nEr möchte uns so schnell wie möglich am Eingang zur Stadt treffen.\n\nWürdet Ihr mich begleiten? Ich habe so eine Ahnung, dass er nicht allein sein wird.", sourceObjective = "Trefft Euch mit Khadgar in Suramar.", completion = "Da seid Ihr ja, Champion. Nun sind wir also vollzählig.", sourceObjectiveStatus = "unverified-source-field" }
quests[40392] = { id = 40392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Schützen", description = "Wir dürfen keine Zeit verschwenden! Wenn Alleria und Thas'dorah in die Hände der Legion gefallen sein sollten, ist es nur eine Frage der Zeit, bis sie für immer verloren sind.\n\nBrecht zur Verheerten Küste auf, sobald Ihr bereit seid, und trefft Euch dort mit der Waldläufergeneralin Windläufer.\n\nSie hat ihren persönlichen Hippogryphen zur Verfügung gestellt, um Euch zur Oberfläche zu bringen.", sourceObjective = "Fliegt mit dem Hippogryphen von Krasus' Landeplatz zur Verheerten Küste und trefft Euch dort mit Vereesa Windläufer.", completion = "Die Weltenwanderer haben die gefangenen Dämonen verhört.\n\nEine dieser widerwärtigen Kreaturen behauptet, den Aufenthaltsort von jemandem zu kennen, der für uns von... größter Bedeutung ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[40395] = { id = 40395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Timewalking \"Heroic\" Random - Nth", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[40397] = { id = 40397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Hidden Treasure Cache" }
quests[40398] = { id = 40398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaman Shrine - Stormheim Water 01 - DGK" }
quests[40399] = { id = 40399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Sailor's Nightmare - twh" }
quests[40400] = { id = 40400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimoperation", description = "Ihr geltet als <verdienter Held/verdiente Heldin> der Allianz, {name}. Wie wir alle habt auch Ihr große Opfer erbracht, um so weit zu kommen.\n\nAber jetzt muss ich noch mehr von Euch verlangen. Werdet Ihr mich anhören?", sourceObjective = "Sprecht mit Vereesa Windläufer.", progress = "Ihr müsst Euch jetzt entscheiden, ob Ihr an meiner Seite kämpfen werdet.", completion = "Jetzt ist die Zeit gekommen, zu handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[40401] = { id = 40401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Weg zurück", description = "Ich muss wieder nach Suramar hineingelangen.\n\nIch wurde ungerechterweise verbannt! Ich kann hier so nicht leben, ich brauche die Energie des Nachtbrunnens...\n\nVor ein paar Tagen habe ich eine Nachricht gesehen, die in eine Wand geritzt war. Es gibt jemanden in den Wassergärten, der Leute in die Stadt schmuggeln kann.\n\nAn der Wand stand: \"Wir werden erneut aus dem Brunnen trinken.\"\n\nNoch eine Konfrontation mit den Wachen überlebe ich nicht. Könntet Ihr an meiner Stelle gehen? Wenn ich wieder in der Stadt bin, kann ich Euch dafür entlohnen.", sourceObjective = "Sucht den Schmuggler.", progress = "Wer seid Ihr, dass Ihr nach Suramar wollt?", completion = "Ich hoffe um unser beider willen, dass niemand Euch gefolgt ist. Wir müssen schnell sein, so nah, wie ich dran bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[40402] = { id = 40402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimoperation", description = "Wie Ihr sehr gut wisst, habe ich die Horde wieder und wieder bekämpft. Die Orcs haben mir und meiner Familie so viel genommen...\n\nAber ich habe Eure Heldentaten und unzähligen Kämpfe für Azeroth mit eigenen Augen gesehen, {name}. Wie wir alle habt auch Ihr große Opfer erbracht und schwere Prüfungen auf Euch genommen, um so weit zu kommen.\n\nNun muss ich Euch um Hilfe bitten. Werdet Ihr mich anhören?", sourceObjective = "Hört Euch Vereesa Windläufers Geschichte an.", progress = "Ihr müsst Euch jetzt entscheiden, ob Ihr an meiner Seite kämpfen werdet.", completion = "Jetzt ist die Zeit gekommen, zu handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[40403] = { id = 40403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimoperation", description = "Es fällt mir nicht leicht, um die Hilfe <eines Blutelfen/einer Blutelfe> zu bitten. Eure Anführer haben den Opfern, die meine Familie und so viele andere erbracht haben, einfach den Rücken zugekehrt.\n\nAber ich habe Eure Heldentaten und unzähligen Kämpfe für Azeroth mit eigenen Augen gesehen, {name}. Wie wir alle habt auch Ihr große Opfer erbracht und schwere Prüfungen auf Euch genommen, um so weit zu kommen.\n\nNun muss ich Euch um Hilfe bitten. Werdet Ihr mich anhören?", sourceObjective = "Hört Euch an, was Vereesa Windläufer zu sagen hat.", progress = "Ihr müsst Euch jetzt entscheiden, ob Ihr an meiner Seite kämpfen werdet.", completion = "Jetzt ist die Zeit gekommen, zu handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[40404] = { id = 40404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Legion Portal" }
quests[40405] = { id = 40405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bristlemaul" }
quests[40406] = { id = 40406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luggut the Eggeater" }
quests[40408] = { id = 40408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendäre Waffen", description = "Unsere Versammlung hat einige unglaublich mächtige Waffen ausgemacht. In den richtigen Händen werden diese heiligen Artefakte uns eine Chance im Kampf gegen die Legion bieten.\n\nWir können nicht alle gleichzeitig suchen. Das Risiko ist zu hoch, wenn wir uns so weit verteilen. Wir müssen uns darauf verständigen, auf welche Waffe wir unsere Bemühungen am sinnvollsten konzentrieren.\n\nDeshalb habe ich Euch hergebeten, {name}. Als einer unserer größten Champions müsst Ihr als Stimme der Vernunft fungieren und unseren nächsten Schritt bestimmen.", sourceObjective = "Wählt eine Artefaktwaffe, nach der Ihr suchen wollt.", completion = "Ausgezeichnete Wahl! Wir haben keine Zeit zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[40409] = { id = 40409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashbringer Chosen" }
quests[40410] = { id = 40410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Hand Chosen" }
quests[40411] = { id = 40411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truthguard Chosen" }
quests[40412] = { id = 40412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azoran muss sterben", description = "Ihr werdet nicht viel Zeit haben, bevor die Legion Eure Anwesenheit auf dem Schiff bemerkt.\n\nSobald Alarm geschlagen wird, werden zahllose Streitkräfte der Legion versuchen, durch dieses Portal an Bord des Schiffs zu gelangen.\n\nDas werde ich nicht zulassen.\n\nIch werde dieses Portal bis zu Eurer Rückkehr verteidigen und gegnerische Verstärkung zurückschlagen. Es liegt an Euch, Azoran zu töten und sein Schiff zu vernichten.\n\nUns bleibt nicht viel Zeit. Ihr müsst schnell und gnadenlos zuschlagen.", sourceObjective = "Besiegt Azoran in der Teufelsseelenbastion.", completion = "Mit Azorans Tod wurde der Legion ein schwerer Schlag versetzt, von dem sie sich nicht so schnell erholen wird.\n\nIhr habt Euch meinen Respekt verdient, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40413] = { id = 40413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amateur Hunters" }
quests[40414] = { id = 40414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devouring Darkness" }
quests[40415] = { id = 40415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinnvoll genutzte Zeit", description = "Dank Eures Respekts für unsere Gepflogenheiten verfügt Ihr jetzt über all das Wissen, das wir Euch lehren können. Geht jetzt, {name}, und tragt unsere Lebensweise zu denjenigen, die gegen die Legion kämpfen.\n\nVielleicht wird es helfen, das Blatt in diesem Krieg zugunsten unserer Welt zu wenden.", sourceObjective = "Erzählt Namha von Eurer Zeit bei den Tauren des Hochbergs.", completion = "Wenn man sich vorstellt, dass Lederverarbeitung schon so lange im Vermächtnis der Hochbergtauren verankert ist, so ist das wirklich erstaunlich.\n\nPlötzlich wünschte ich, dass ich über die Vergangenheit meines Volks auch so viel wüsste wie sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[40416] = { id = 40416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[40417] = { id = 40417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan ruft!", description = "Es ist jetzt von größter Bedeutung, dass Ihr Euch auf den Tanaandschungel konzentriert und dort eine Stellung errichtet, bevor Ihr Euch von anderen Dingen ablenken lasst.\n\nDer Kriegshäuptling wartet auf Euch im Hauptgebäude. Es wäre klug, ihn nicht allzu lange warten zu lassen...", sourceObjective = "Sprecht mit Kriegshäuptling Vol'jin im Hauptgebäude Eurer Garnison.", completion = "<Der Kriegshäuptling studiert mit sorgenvoller Miene eine Karte des Tanaandschungels und der umgebenden Gebiete.>\n\nAh, Kommandant {name}! Die Stimme der Horde in Draenor. Ihr habt Eure Sache hier gut gemacht und unseren Feinden mächtig zugesetzt. Thrall sagt, Ihr übertrefft seine kühnsten Erwartungen.\n\nEs wird Zeit, die Sache zu beenden. Seid Ihr bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[40418] = { id = 40418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan ruft!", description = "Es ist jetzt von größter Bedeutung, dass Ihr Euch auf den Tanaandschungel konzentriert und dort eine Stellung errichtet, bevor Ihr Euch von anderen Dingen ablenken lasst.\n\nDer König mitsamt seinem ganzen Gefolge wartet auf Euch im Hauptgebäude. Es wäre klug, ihn nicht allzu lange warten zu lassen...", sourceObjective = "Sprecht mit König Varian Wrynn im Hauptgebäude Eurer Garnison.", completion = "<Der König studiert die Karten des Tanaandschungels und der umgebenden Gebiete.>\n\n{name}! Die Allianz ist Euch für die Gründung dieser Garnison zu großem Dank verpflichtet. Dank Eurer Tapferkeit und Eures Führungstalents können wir diesen Krieg hier auf Draenor und nicht inmitten unserer Heimatlande führen.\n\nJetzt ist die Zeit gekommen, diese Sache zu beenden. Seid Ihr bereit für den letzten Feldzug?", sourceObjectiveStatus = "unverified-source-field" }
quests[40419] = { id = 40419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungsmission", description = "Der Dämon hat uns erzählt, wie man ein Portal zu jener Welt öffnet, in der Alleria gefangen gehalten werden soll. Wir beide können hindurchgehen, um zu sehen, ob er die Wahrheit gesagt hat.\n\nFür den Fall, dass es sich um eine Falle handelt, hat mir Magus Sonnauge einen Portalstein gegeben, der uns zurück nach Dalaran bringt.\n\nDiese Dämonenmagie ist jedem Magier ein Gräuel, also sollten wir uns beeilen. Vor mir aus können wir aufbrechen, {name}.", sourceObjective = "Reist durch das Portal und rettet Alleria Windläufer.", completion = "Wir konnten Alleria zwar nicht retten, aber zumindest wissen wir jetzt, dass sie dort war. Wir werden sie finden... Ich weiß es einfach!\n\nThas'dorah war lange Zeit ein Symbol der Windläuferfamilie, aber bis Alleria zurückkehrt, gehört er in Eure Hände.\n\nVersammelt damit die größten {class} von Azeroth um Euch, um die Brennende Legion zurück in den Abgrund zu treiben!", sourceObjectiveStatus = "unverified-source-field" }
quests[40422] = { id = 40422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: VotW Started" }
quests[40423] = { id = 40423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unethical Adventurers" }
quests[40424] = { id = 40424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Reise", description = "Die Eingänge der Stadt sind schwer bewacht. Er muss von einem anderen Weg wissen.\n\nDank dieses Weins bin ich stark genug, um die Reise zu ihm anzutreten. Ich fürchte nur, dass ich mich nicht verteidigen oder weglaufen kann, wenn ich angegriffen werde.\n\nIhr werdet mich begleiten, {race}. Ihr und dieser Astoril seid jetzt meine einzige Überlebenschance.\n\nIch erinnere mich, dass mich beim Verlassen der Stadt diese Laternen hierhergeführt haben. Wenn wir ihnen folgen, sollten wir auf dem richtigen Weg sein.", sourceObjective = "Folgt den Laternenpfählen, um Iadreth zu Astoril zu bringen.", progress = "Ich dachte schon, dass Euch etwas im Wald zugestoßen sei. Schön, dass ich mich geirrt habe.", completion = "Ausgezeichnet. Ihr habt Euren Part erfüllt.\n\nIhr könnt gewiss sein, dass Ihr mir einen großen Dienst erwiesen habt.\n\nHier, nehmt diese Entlohnung, eine kleine Anerkennung für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[40425] = { id = 40425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Pollous the Fetid" }
