quests[40456] = { id = 40456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Gorebeak" }
quests[40469] = { id = 40469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Vorbereitungen", description = "Für unsere Reise nach Suramar werden wir Verpflegung brauchen. Und mit Euch beiden im Schlepptau können wir nicht einfach am Tor Halt machen und etwas kaufen, oder?\n\nDie Wassergärten waren früher ein beliebter Ort zum Entspannen und um Kontakte zu pflegen. Vor den Patrouillen war es ganz normal, dort ein bisschen Manawein für spätere Zwecke zu verstecken.\n\nUnd damit kommt Ihr ins Spiel: Holt Euch ein paar der Vorräte und bringt sie Eurer Freundin. Danach sucht mich in den Ruinen nördlich der Stadt auf. Wir werden bald bereit zum Aufbruch sein.", sourceObjective = "Besorgt 6 versteckte Vorräte.", progress = "Habt Ihr den Schmuggler gefunden? Was hat er gesagt?", completion = "Ist das etwa Manawein? Für mich?\n\n<Iadreth trinkt die Flasche gierig in einem Zug aus.>\n\nIch möchte Euch und diesem Astoril danken. Ich wäre hier draußen sicher zugrunde gegangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40470] = { id = 40470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensqualität", description = "Ich habe Angst, {name}. Wir sind fast zu Hause, so nah an der Rettung...\n\nAstoril sagt, er kenne den Weg und könne uns sicher dorthinbringen. Ich glaube ihm, aber Ihr habt uns schon so lange beschützt. Werdet Ihr diese Sache mit uns bis zum Ende durchstehen?", sourceObjective = "Folgt Iadreth.", completion = "Eine wahrhaft beunruhigende Geschichte.\n\nIhr habt das Richtige getan, {name}. Jetzt wird er unseren Leuten kein Leid mehr zufügen.", sourceObjectiveStatus = "unverified-source-field" }
