quests[40495] = { id = 40495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulthalesh, Sense der Totenwinde", description = "Laut dem Buch wurden die Dunklen Reiter zuletzt an einem Ort namens Anwesen der Dunstmantels gesehen. Wenn <Freund/Freundin> diese Reiter findet, kann <er/sie> sich Ulthalesh schnappen!\n\nCalydus wird hier auf Eure Rückkehr warten. Findet Ulthalesh, <Freund/Freundin>!", sourceObjective = "Beginnt Eure Suche nach der Sense der Totenwinde beim Anwesen der Dunstmantels im Dämmerwald.", progress = "Und warum genau sollte ich Euch helfen, {class}?", completion = "Ich habe kaum eine andere Wahl. Einen weiteren Angriff der Dunklen Reiter würde ich nicht überstehen, und Ihr seid offensichtlich mit großer Kraft gesegnet.\n\nIch werde Euch helfen, die von Euch gesuchte Waffe zu finden. Aber im Gegenzug verlange ich, die anderen Artefakte ihren rechtmäßigen Besitzern zurückbringen zu dürfen.\n\nHaben wir also eine Abmachung, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[40496] = { id = 40496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 089 - Rockcrawler Chasm - M (RKS)" }
