quests[40514] = { id = 40514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revil Convinced" }
quests[40515] = { id = 40515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterlicher Spaziergang", description = "Der Geistwandler, den ihr an der Flusswindung gerettet habt, ist schon seit seiner Ankunft unerträglich. Er besteht darauf, Euch die Bräuche unseres Volkes zu erklären, damit Ihr verstehen könnt, was bevorsteht.\n\nEr ist schon merkwürdig, selbst für einen Geistwandler.\n\nDennoch würde nur ein Narr seine Erkenntnisse ignorieren. Bitte unterhaltet Euch mit ihm, wenn Ihr etwas Zeit habt.", sourceObjective = "Sprecht mit Geistwandler Ebenhorn.", completion = "Ihr habt Mayla zum Lächeln gebracht. Das ist das erste Mal seit... überhaupt, dass ich sie habe lächeln sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40516] = { id = 40516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dawning Bit" }
quests[40517] = { id = 40517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefallene Löwe", description = "Ich habe dieses Schiff seit meiner Rückkehr nicht verlassen. Die Flotte muss für den Krieg bereit sein. Ich weiß nicht, wo man uns brauchen wird, doch wenn wir gerufen werden, sind wir bereit.\n\nUm ehrlich zu sein... die Ablenkung passt mir gut. Die anderen erweisen Varian die letzte Ehre, aber ich... ich schaffe es nicht, mich diesem Sarg zu nähern. Ich kann seinem Sohn nicht in die Augen sehen.\n\nVarian gab mir diesen Brief für Anduin. Bitte überbringt ihn an meiner statt.", sourceObjective = "Bringt König Varians Brief zu König Anduin.", progress = "Willkommen, {name}. Es freut mich, dass Ihr die Schlacht überstanden habt. Habt Ihr etwas für mich?", completion = "<Anduin seufzt und beginnt den Brief seines Vaters zu lesen. Tränen sammeln sich in seinen Augen und er schweigt einige Momente lang.>\n\nIch danke Euch, dass Ihr mir dies überbracht habt, {name}. Es bedeutet mir... mehr als ich ausdrücken könnte. Ich wünschte, Graumähne hätte sich dazu imstande gefühlt, ihn mir selbst zu bringen, doch er ist auf Rache aus.\n\nDas kann ich weder ihm noch Jaina verdenken, doch wir müssen einen besseren Weg finden.\n\nAber genug davon. Es ist gut, dass Ihr hier seid. Helden wie Euch werden wir in den vielen bevorstehenden Schlachten brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40518] = { id = 40518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Verheerte Küste", description = "Euer Kriegsschiff erwartet Euch am Ende des Docks, {name}. Möge Euch Eure Waffe heute viele Trophäen einbringen.\n\nDer Kriegshäuptling ist schon an Land gegangen. Ich denke, Ihr müsst einfach nur der Spur Dämonenblut folgen.", sourceObjective = "Reist auf Kapitän Russos Schiff zur Verheerten Küste.", completion = "Gut, dass Ihr wieder auf den Beinen seid, {name}. Viele tapfere Soldaten, die zur Verheerten Küste gesegelt sind, hatten nicht so viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[40519] = { id = 40519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion: Die Rückkehr der Legion", description = "Helden der Allianz, ich schreibe Euch in Azeroths dunkelster Stunde. Die brennenden Armeen der Legion kehren aus dem Schlund der Hölle zurück.\n\nUnsere Flotte bricht unverzüglich zu den Verheerten Inseln auf. Wie eine große Lanze werden wir die Reihen der Legion durchstoßen und sie in den Nether zurückdrängen, aus dem sie hervorgekrochen sind.\n\nEuer Schiff wartet im Hafen von Sturmwind. Verliert keine Zeit.", sourceObjective = "Meldet Euch bei Musterungsoffizier Lee im Hafen von Sturmwind.\n\nBereitgestellter Gegenstand:", completion = "Seid gegrüßt, {name}. Ich habe Eure Schiffszuteilung hier.\n\nAber zunächst müssen wir uns vorbereiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[40520] = { id = 40520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick in die Vergangenheit", description = "Ich möchte, dass Ihr aus erster Hand erfahrt, was Huln Hochberg während des Krieges der Ahnen in einer einzigen Schlacht vollbringen konnte.\n\nUnd dazu benötige ich ein paar sehr spezielle Zutaten. Sie sind nicht schwer zu finden. Schaut Euch einfach in der Nähe von Donnertotem um.", sourceObjective = "Sammelt eine Flasche mit Luftfunken, Mu'shas Tränen und einen Dunkelsplitterkristall.", progress = "Mit der Magie von Erde, Luft und Wasser sind wir hier in den Bergen sehr vertraut.", completion = "Ah, die werden unserem Zweck äußerst dienlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[40521] = { id = 40521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - W1 - Demon Attack Complete" }
quests[40522] = { id = 40522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Horde", description = "Es ist ein Wunder, dass überhaupt jemand von unseren Truppen das Blutbad an der Verheerten Küste überstanden hat. Wenn Lady Sylvanas nicht da gewesen wäre...\n\nHochfürst Saurfang erwartet Euch in der Feste Grommash. Er sagt nicht, warum... aber er besteht darauf, dass ich Euch zu ihm schicke.", sourceObjective = "Geht zur Feste Grommash und erfahrt vom Schicksal der Horde.", progress = "Uns stehen düstere Zeiten bevor.", completion = "Ihr habt der Horde bereits gut gedient, {name}.\n\nMan wird noch mehr von Euch fordern... viel mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[40523] = { id = 40523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edle Freunde", description = "Entschuldigt bitte, <werter Herr/werte Dame>, aber seid Ihr sicher, dass Ihr hier richtig seid? Wir handeln hier nämlich nur mit feinsten Juwelen.\n\nOh, ich verstehe... Ihr seid auch <ein Edelsteinexperte/eine Edelsteinexpertin>. Nun, dann könnten wir ja vielleicht zusammenarbeiten.\n\nBitte stellt Euch meinen Geschäftspartnern vor, damit sie Euch kennenlernen und erfahren können, was Ihr ihnen anzubieten habt.", sourceObjective = "Stellt Euch Jonas Timotheus und Sminx Glasauge vor.", progress = "Macht Euch erst mal bekannt. Dann können wir über das Geschäft sprechen.", completion = "Ich selbst bin die Besitzerin dieses Unternehmens. Wenn Ihr Fragen zu unserem Laden habt, dann kommt gleich zu mir.\n\nUnd jetzt kommen wir zum Geschäft.", sourceObjectiveStatus = "unverified-source-field" }
quests[40524] = { id = 40524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz besonderer Ring", description = "{name}! Reden wir mal über Klunker. Ich suche einen Ring.\n\nWisst Ihr, die Elfen in Azsuna waren zu ihrer Zeit Meister der Juwelierskunst... behaupten zumindest alle. In den Büchern geht es immer um einen Ring namens \"Farondis' Band\". Kann ja nichts schaden, wenn wir uns danach erkundigen.\n\nMachen wir uns auf den Weg nach Azsuna. Ich bin bestimmt schneller da!", sourceObjective = "Sucht nach dem Schrein von Aldiir am Zerfallenen Palast in Azsuna und lest Euch die Legendenerzählung durch.", completion = "Der Ring wurde also von Murlocs geklaut? Dadurch bietet sich doch eine weitere Zusammenarbeit für uns beide an!\n\nMit Euch kann man nicht nur Pferde, sondern auch Ringe stehlen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[40525] = { id = 40525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glückliche Zusammenführung", description = "Ich mag Eure zupackende Art, {name}. Ihr habt die Durchschlagskraft und ich weiß, wohin wir zielen müssen!\n\nDie nächste Aufgabe ist wie gemacht für Euch. Findet den Ring... oder was die Murlocs davon übrig gelassen haben.", sourceObjective = "Sucht die drei Teile von Farondis' Band und bringt sie zu Jonas Timotheus.", progress = "Wie verläuft die Jagd nach dem Ring?", completion = "Ihr habt alle Teile!\n\n<Jonas sieht sie sich genau an und nickt zustimmend.>\n\nJa, den bekomme ich wieder hin. Kein Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[40526] = { id = 40526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinschliff", description = "Nun, ich habe es geschafft, den Ring zu reparieren. Der Edelstein benötigt aber noch etwas Feinarbeit.\n\nHe... Ihr seid doch <ein Juwelenschleifer/eine Juwelenschleiferin>, {name}. Ihr habt das nötige Werkzeug, also schleift doch die Juwelen!", sourceObjective = "Verwendet Jonas' Edelsteinklemme, um einen geschliffenen Himmelsstein zu erhalten.", progress = "Wie ist es gelaufen?", completion = "Oh, ja! Das ist ein einwandfreier Himmelsstein.\n\n<Jonas setzt den Edelstein auf den reparierten Ring.>\n\nGenau wie ein Maler oder ein Dichter erschaffe auch ich Meisterwerke!\n\nAber da Ihr all die Laufarbeit erledigt habt, werde ich die Vorlage für diesen Ring mit Euch teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40527] = { id = 40527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinschliff", description = "Nun, ich habe es geschafft, den Ring zu reparieren. Der Edelstein benötigt aber noch etwas Feinarbeit.\n\nHe... Ihr seid doch <ein Juwelenschleifer/eine Juwelenschleiferin>, {name}. Ihr habt das nötige Werkzeug, also schleift doch die Juwelen!", sourceObjective = "Verwendet Jonas' Edelsteinklemme, um einen geschliffenen Tiefenbernstein zu erhalten.", progress = "Wie ist es gelaufen?", completion = "Oh, ja! Das ist ein einwandfreier Tiefenbernstein.\n\n<Jonas setzt den Edelstein auf den reparierten Ring.>\n\nGenau wie ein Maler oder ein Dichter erschaffe auch ich Meisterwerke!\n\nAber da Ihr all die Laufarbeit verrichtet habt, werde ich die Vorlage für diesen Ring mit Euch teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40528] = { id = 40528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinschliff", description = "Nun, ich habe es geschafft, den Ring zu reparieren. Der Edelstein benötigt aber noch etwas Feinarbeit.\n\nHe... Ihr seid doch <ein Juwelenschleifer/eine Juwelenschleiferin>, {name}. Ihr habt das nötige Werkzeug, also schleift doch die Juwelen!", sourceObjective = "Verwendet Jonas' Edelsteinklemme, um einen geschliffenen Azsunit zu erhalten.", progress = "Wie ist es gelaufen?", completion = "Oh, ja! Das ist ein einwandfreier Azsunit.\n\n<Jonas setzt den Edelstein auf den reparierten Ring.>\n\nGenau wie ein Maler oder ein Dichter erschaffe auch ich Meisterwerke!\n\nAber da Ihr all die Laufarbeit verrichtet habt, werde ich die Vorlage für diesen Ring mit Euch teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40529] = { id = 40529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keinerlei Verschwendung", description = "Das Sondieren ist unsere maßgebliche Technik zur Gewinnung von Edelsteinen. Dabei fallen unweigerlich kleine und unnütze Edelsteinsplitter an.\n\nViele der Edelsteinläden schenken diesen Splittern keine Beachtung, aber wir hier bei Cartier & Co verschwenden nicht das kleinste bisschen.", sourceObjective = "Sammelt 5 Edelsteinsplitter für Tiffany Cartier. Edelsteinsplitter erhaltet Ihr durch Sondieren von Roherz oder den Ankauf im Auktionshaus.", progress = "Bitte sorgt dafür, dass sie auf Euren \"Abenteuern\" nicht mit Blut besudelt werden.", completion = "<Tiffany schaut sich die Edelsteinsplitter an.>\n\nJa, damit können wir etwas anfangen.\n\nSie sind anders als jene, mit denen ich gewohnt bin zu arbeiten, aber wir sind hier ja auch nicht mehr in Nordend.\n\nHier ist eine Vorlage für einen der neueren Edelsteine, mit dem ich gearbeitet habe. Ich nenne ihn den vielseitigen Himmelsstein.", sourceObjectiveStatus = "unverified-source-field" }
quests[40530] = { id = 40530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genaue Begutachtung", description = "{name}, wenn ich etwas nicht ausstehen kann, ist es Verleumdung. Es geht das Gerücht um, dass eine meiner letzten Auftragsarbeiten eine Fälschung war.\n\nWir müssen diesen Gerüchten so schnell wie möglich ein Ende setzen.\n\nIch möchte, dass Ihr die Kunden besucht, für die ich zuletzt gearbeitet habe, und ihre Edelsteine untersucht. Wenn Ihr tatsächlich über so viel Edelsteinexpertise verfügt, solltet Ihr einen falschen Edelstein sofort erkennen.\n\nHier ist die Liste meiner Kunden. Kehrt sofort zurück, wenn sich herausstellt, dass an den Gerüchten etwas Wahres dran ist.", sourceObjective = "Sucht die Kunden des Juwelierladens in Dalaran auf und erstattet danach Tiffany Bericht.", completion = "Was habt Ihr da?\n\n<Tiffany öffnet den Beutel und entnimmt einen Edelstein. Sie untersucht ihn und lässt ihn dann zu Boden fallen, wo er in tausend Stücke zerspringt.>\n\nWer hat diese Juwelen ausgeliefert...\n\nWINSTON!!! Dieser Dieb! Wie kann er es wagen, meine Edelsteine gegen diese... jämmerlichen Fälschungen auszutauschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40531] = { id = 40531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgängiger Angestellter", description = "Ich schwöre, wenn ich ihn finde, dann...\n\n<Tiffany sieht Euch in die Augen und gewinnt ihre Fassung zurück.>\n\n{name}, ich möchte, dass Ihr meinen FRÜHEREN Angestellten Harold Winston findet. Er kann von hier aus noch nicht weit gekommen sein.\n\nUnd wenn Ihr ihn findet, dann nehmt ihm bitte mein gestohlenes Eigentum ab und bringt es mir zurück.\n\nDie genaue Vorgehensweise überlasse ich Euch. Und keine Sorge bezüglich der Edelsteine von Frau Meer... Ich werde ihr persönlich Ersatz zukommen lassen.", sourceObjective = "Sucht nach Harold Winston in der Schattenseite von Dalaran.", progress = "Habt Ihr ihn gefunden? Konntet Ihr die Edelsteine sicherstellen?", completion = "<Tiffany nimmt Euch den Beutel ab und holt die Edelsteine heraus. Sie sieht sich jeden einzelnen genau an.>\n\nSehr gut, sie sind alle da. Und es scheint sich bei ihnen um die Originale zu handeln.\n\nUnd was habt Ihr mit Harold... Ach, schon gut. Ich will es gar nicht wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40532] = { id = 40532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut abgeschnitten", description = "Da Ihr mir bis jetzt treu und verlässlich zu Diensten wart, werde ich Euch zeigen, wie man einen tödlichen Tiefenbernstein schleift.\n\nWir werden dazu mein Schleifwerkzeug verwenden. Wenn Ihr also bereit seid, dann setzt Euch einfach davor.", sourceObjective = "Stellt mithilfe von Tiffanys Schneidewerkzeug einen tödlichen Tiefenbernstein her.", progress = "Achtet darauf, den Rohedelstein nicht zu zerbrechen. Wir haben nicht gerade unbegrenzte Vorräte davon.", completion = "<Tiffany begutachtet Eure Arbeit.>\n\nAha. Diese Facette hier hätte ich in einem anderen Winkel geschliffen... aber das kann man so durchgehen lassen.\n\nIch schreibe Euch meine Vorlage auf. Dann könnt Ihr versuchen, mehr wie ich zu arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[40533] = { id = 40533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut abgeschnitten", description = "Da Ihr mir bis jetzt treu und verlässlich zu Diensten wart, werde ich Euch zeigen, wie man einen spiegelnden Azsunit schleift.\n\nWir werden dazu mein Schleifwerkzeug verwenden. Wenn Ihr also bereit seid, dann setzt Euch einfach davor.", sourceObjective = "Stellt mithilfe von Tiffanys Schneidewerkzeug einen spiegelnden Azsunit her.", progress = "Achtet darauf, den Rohedelstein nicht zu zerbrechen. Wir haben nicht gerade unbegrenzte Vorräte davon.", completion = "<Tiffany begutachtet Eure Arbeit.>\n\nAha. Diese Facette hier hätte ich in einem anderen Winkel geschliffen... aber das kann man so durchgehen lassen.\n\nIch schreibe Euch meine Vorlage auf. Dann könnt Ihr versuchen, mehr wie ich zu arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[40534] = { id = 40534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut abgeschnitten", description = "Da Ihr mir bis jetzt treu und verlässlich zu Diensten wart, werde ich Euch zeigen, wie man einen meisterlichen Königinnenopal schleift.\n\nWir werden dazu mein Schleifwerkzeug verwenden. Wenn Ihr also bereit seid, dann setzt Euch einfach davor.", sourceObjective = "Stellt mithilfe von Tiffanys Schneidewerkzeug einen meisterlichen Königinnenopal her.", progress = "Achtet darauf, den Rohedelstein nicht zu zerbrechen. Wir haben nicht gerade unbegrenzte Vorräte davon.", completion = "<Tiffany begutachtet Eure Arbeit.>\n\nAha. Diese Facette hier hätte ich in einem anderen Winkel geschliffen... aber das kann man so durchgehen lassen.\n\nIch schreibe Euch meine Vorlage auf. Dann könnt Ihr versuchen, mehr wie ich zu arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[40535] = { id = 40535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufzucht der Drogbar", description = "Manche Dinge sprechen sich schnell herum in Dalaran, {name}. Und zurzeit wird behauptet, dass sich irgendwo in Val'sharah ein Meisterjuwelier aufhält.\n\nIch möchte, dass Ihr ihn oder sie ausfindig macht. Vielleicht hat diese Person ja Vorlagen, die unserem Geschäft dienlich sein könnten.\n\nIch habe den Namen \"Lasune Sternenklinge\" im Zusammenhang mit diesen Gerüchten gehört. Vielleicht ist sie ein guter Ausgangspunkt für Eure Suche.", sourceObjective = "Sprecht mit Lasune Sternenklinge in Val'sharah über den Aufenthaltsort des Juwelierskunstmeisters.", progress = "Diese verdammten Harpyien haben Jabrul überfallen!", completion = "Jabrul möchte Euch danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40536] = { id = 40536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erst Bruls, dann der Rest", description = "Ihr möchtet also erlernen, was Jabrul über Edelsteine weiß?\n\nGut, aber zuvor benötigt Jabrul Eure Hilfe. Bevor wir gehen können, braucht Jabrul immer noch Harpyienhalsketten.\n\nHaltet die Harpyien in Schach, während Jabrul sich ihre Halsketten nimmt. Dann wird Jabrul Euch mit seinem Wissen belohnen.", sourceObjective = "Beschützt Jabrul, während er die Halsketten der Harpyien einsammelt, und bringt ihn dann sicher zurück ins nahe gelegene Nachtelfenlager.", completion = "Es fühlt sich gut an, wieder da draußen zu sein. Wie versprochen wird Jabrul ein Teil seines Wissens mit Euch teilen.\n\nWoran seid Ihr denn vordringlich interessiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[40537] = { id = 40537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutspende", description = "Hey, {name}! Ich muss Euch unbedingt etwas erzählen, aber das muss unter uns Schreibern bleiben.\n\n<Zooey zwinkert Euch zu und holt einen großen Folianten hervor.>\n\nDas ist das blutgebundene Register. Wenn Ihr Euren Namen eintragt, lernt Ihr, wie man \"Blutverträge\" herstellt. Das tut zwar ein bisschen weh, ist die Sache aber unbedingt wert!\n\nIch selbst kenne derzeit einen von ihnen und freue mich immer, ihn anzuwenden, weil... also... Ihr werdet schon sehen.\n\nUnd? Habt Ihr Interesse daran?", sourceObjective = "Unterschreibt das blutgebundene Register.", completion = "So, mal sehen. Ja, das sieht alles in Ordnung aus und anscheinend nimmt der Zauber schon Einfluss auf Euch.\n\nJetzt könnt Ihr die tödlichen und wirklich gruseligen \"Blutverträge\" erlernen. BuuuhUUUuuu.\n\n<Zooey legt einen kleinen Auftritt hin, während sie ein Gespenst imitiert.>\n\nHaha, war nur ein Spaß, {name}. Aber im Ernst: Diese Dinger können ganz schön gefährlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[40538] = { id = 40538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgeschrittene Lektionen", description = "Schön, Euch wiederzusehen, {name}.\n\nWir sind wohl beide seit unserem letzten Gespräch sehr fleißig gewesen. Ich habe etwas, das Euch interessieren könnte.\n\nVor Kurzem ist eine Lieferung seltener Edelsteine namens Mahlstromsaphire endlich im Laden eingetroffen.\n\nIch habe eine wundervolle Vorlage für sie erstellt und möchte Euch zeigen, wie man etwas Nützliches aus ihnen schleifen kann.", sourceObjective = "Stellt mithilfe von Tiffanys Schneidewerkzeug einen fein gearbeiteten Mahlstromsaphir her.", progress = "Ich rate Euch, bei diesen Edelsteinen eine noch ruhigere Hand als sonst zu bewahren.", completion = "<Tiffany schaut sich den Edelstein an und nickt.>\n\nSehr gute Arbeit, {name}. Offensichtlich haben sich Eure Fertigkeiten verbessert, seit Ihr letztes Mal etwas für mich geschliffen habt.\n\nViel Freude mit der Vorlage. Sie ist einer meiner besten.", sourceObjectiveStatus = "unverified-source-field" }
quests[40539] = { id = 40539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskretes Geschäft", description = "Man erzählt sich von Euch, dass Ihr Aufträge zuverlässig und diskret abwickelt.\n\nUnd ich habe einen Auftrag für Euch: Ich brauche einen neuen Satz Dietriche, aber nicht einfach irgendeinen Satz.\n\nIch brauche etwas Spezielles, das nicht bricht, wenn man zu viel Druck ausübt.\n\nIch denke da an einen Satz Diamantdietriche. Und damit meine ich das Material, nicht die Form.\n\nUnd? Wollt Ihr den Auftrag annehmen?", sourceObjective = "Beschafft einen Satz Diamantdietriche für Clive Cozen.", progress = "Versucht, nicht zu viel Aufhebens darum zu machen, ja?", completion = "<Clive schaut sich die Dietriche an.>\n\nNicht schlecht... nicht schlecht.\n\nHört zu, Ihr habt mir heute einen großen Gefallen getan. Ich weiß jetzt, wen ich wieder kontaktieren muss, sollte ich einmal einen neuen Satz brauchen.\n\n<Clive zwinkert Euch listig zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40540] = { id = 40540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abberufung", description = "{name}, ich habe ein Art... Brief gefunden. Eine in eine flache Steintafel gemeißelte Nachricht.\n\nDieser Juweliermeister, den Ihr in Val'sharah ausfindig gemacht habt, fragt nach Euch. Er sagt, dass er sich derzeit in Sturmheim aufhält.\n\nWenn Ihr ihn seht, dann teilt ihm doch bitte mit, dass wir nicht mehr wünschen, dass er nach Euch schickt. Das bringt nur jede Menge Unruhe in unsere Abläufe.", sourceObjective = "Sucht nach Jabrul in Sturmheim.", completion = "Schön, Euch wiederzusehen, {name}. Jabrul möchte wissen, ob Ihr noch weitere Vorlagen erlernen möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[40541] = { id = 40541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glanz aus dem Jenseits", description = "Bevor Euch Jabrul seine Vorlagen lehrt, müsst Ihr ihm bei einem ganz besonderen Projekt helfen.\n\nJabrul hat einen Edelstein, der Sturmenergie einfangen kann. Je mehr Blitze er einfängt, desto heller leuchtet er.\n\nJabrul findet, dass die Macht der Sturmdrachen in seinem Edelstein besser aufgehoben ist, anstatt damit die Himmel über Sturmheim zu terrorisieren.\n\nSeid Ihr nicht auch dieser Meinung?", sourceObjective = "Wendet das leitfähige Juwel auf die Leichen von 10 Sturmjägern an.", completion = "Jabrul hat in seinem Leben noch nie so ein Strahlen gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40542] = { id = 40542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Nashal", description = "Tödliches Auge der Prophezeiung... eine gute Wahl. Bevor wir schleifen können, benötigen wir allerdings Edelsteine.\n\nHier steht die riesige Statue von Nashal, einem uralten Vrykul. In seinen Augenhöhlen findet Ihr zwei der Steine, die wir benötigen.\n\nKlettert die Statue hinauf und entnehmt ihr die Edelsteinaugen. Kehrt dann zu Jabrul zurück.", sourceObjective = "Beschafft 2 Augen von Nashal.", progress = "Jabrul kann es kaum erwarten, diese Edelsteine aus der Nähe zu sehen.", completion = "Ich hoffe, die waren nicht zu schwer für einen kleinen Brul wie Euch.\n\nAber die reichen auf jeden Fall, um Euch eine schöne Vorlage zu zeigen.\n\n<Jabrul beginnt damit, einen Edelstein nach einer Vorlage zu schleifen, während er Euch gleichzeitig die Arbeitsschritte erklärt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40543] = { id = 40543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Nashal", description = "Spiegelndes Morgenlicht... eine gute Wahl. Bevor wir schleifen können, benötigen wir allerdings Edelsteine.\n\nHier steht die riesige Statue von Nashal, einem uralten Vrykul. In seinen Augenhöhlen findet Ihr zwei der Steine, die wir benötigen.\n\nKlettert die Statue hinauf und entnehmt ihr die Edelsteinaugen. Kehrt dann zu Jabrul zurück.", sourceObjective = "Beschafft 2 Augen von Nashal.", progress = "Jabrul kann es kaum erwarten, diese Edelsteine aus der Nähe zu sehen.", completion = "Ich hoffe, die waren nicht zu schwer für einen kleinen Brul wie Euch.\n\nAber die reichen auf jeden Fall, um Euch eine schöne Vorlage zu zeigen.\n\n<Jabrul beginnt damit, einen Edelstein nach einer Vorlage zu schneiden, während er Euch gleichzeitig die Arbeitsschritte erklärt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40544] = { id = 40544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Nashal", description = "Meisterlicher Schattenrubin... eine gute Wahl. Bevor wir schleifen können, benötigen wir allerdings Edelsteine.\n\nHier steht die riesige Statue von Nashal, einem uralten Vrykul. In seinen Augenhöhlen findet Ihr zwei der Steine, die wir benötigen.\n\nKlettert die Statue hinauf und entnehmt ihr die Edelsteinaugen. Kehrt dann zu Jabrul zurück.", sourceObjective = "Beschafft 2 Augen von Nashal.", progress = "Jabrul kann es kaum erwarten, diese Edelsteine aus der Nähe zu sehen.", completion = "Ich hoffe, die waren nicht zu schwer für einen kleinen Brul wie Euch.\n\nAber die reichen auf jeden Fall, um Euch eine schöne Vorlage zu zeigen.\n\n<Jabrul beginnt damit, einen Edelstein nach einer Vorlage zu schleifen, während er Euch gleichzeitig die Arbeitsschritte erklärt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40545] = { id = 40545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So ein Schrott!", description = "Das ist eine Katastrophe! Nein, noch schlimmer, das ist eine Verschwörung!\n\nAls ich erfahren habe, dass die Legion zurückgekehrt ist, sagte ich zu mir selbst: \"Hobart, jetzt kannst du dich beweisen!\"\n\nAlso habe ich genug Waffen hergestellt, um diese Dämonen zu den Anfängen der Zeit zurückzuschießen.\n\nUnd was passiert, als wir hier endlich ankommen? Alle \"finden\" diese antiken Artefakte, mit denen man die Dämonen bekämpfen kann!\n\nKurz gesagt: Ich habe zu viele Waffen und muss einige davon loswerden.", sourceObjective = "Bringt die Waffenkiste zu Filgo Schrottpodex in der Schattenseite.\n\nBereitgestellter Gegenstand:", completion = "Was für ein prächtiger Haufen Waffen! Die sind bestimmt von einem Transportgreifen gefallen, was?\n\n<Filgo zwinkert Euch verschwörerisch zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40546] = { id = 40546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Natur", description = "Jabrul will Euch seine besonderen Kristalle zeigen. Niemand weiß, wofür sie gut sind. Sehr geheimnisvoll.\n\nWenn Ihr lernen wollt, wie man einen macht, wird Jabrul es Euch gerne zeigen.\n\nHoch in den Bergen leben die Sturmdrachen. Sie brennen mit ihrem Blitzatem Höhlen in die Klippen, und manchmal wird es dabei so heiß, dass sie Stein in Kristall verwandeln.\n\nHolt ein solches Kristallstück und bringt es Jabrul.", sourceObjective = "Beschafft ein Stück Drachenglas.", progress = "Habt Ihr den Stein?", completion = "Ein ausgezeichnetes Exemplar. Und jetzt passt gut auf...\n\n<Jabrul beginnt, das Glas in eine interessante Form zu schneiden und erklärt dabei, welchen Einfluss die Form auf sein Verhalten hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40547] = { id = 40547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paket nach Dalaran", description = "Jabrul dachte, er würde gern nach Dalaran gehen und Edelsteinvorlagen mit den Meisterjuwelieren dort diskutieren.\n\nAber Jabrul weiß nicht, wie er dort hinkommen soll. Jabrul hat aber eine interessante Idee.\n\nWenn Ihr Jabrul per Post nach Dalaran schickt, wird er ganz sicher dort ankommen.", sourceObjective = "Steckt Jabrul in eine Kiste und schickt sie dem Juwelierladen Cartier & Co.", progress = "Jabrul ist ja SOOO gespannt!", completion = "Die Reise war unbequemer als Jabrul dachte. Aber jetzt ist Jabrul hier.\n\nJabrul kann es kaum erwarten, mit den Meistern hier zu arbeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[40556] = { id = 40556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jabrul braucht Euch", description = "Hallo, {name}.\n\nJabrul benötigt Eure Hilfe. Könntet Ihr bitte nach Azsuna kommen und Jabrul aufsuchen?\n\nDanke,\n\nJabrul", sourceObjective = "Sucht nach Jabrul in Azsuna.", completion = "{name}, es ist schön, Euch wiederzusehen! Nun hört zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[40557] = { id = 40557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Clive Cozen Leave" }
quests[40558] = { id = 40558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eckige muss ins Runde", description = "Ihr bewundert die Apparatur auf der Ladentheke. Das Drücken des Schalters darauf scheint allerdings nichts zu bewirken.\n\nTiffany erklärt Euch, dass sämtliche Edelsteinkomponenten dieses alten Spielzeugkistchens zerbrochen sind.\n\nWenn Ihr Ersatz beschaffen könnt, würde sie das Kistchen reparieren und Euch zeigen können, wie man so etwas herstellt.", sourceObjective = "Findet alle 6 erforderlichen Komponenten auf der ganzen Welt. In Tiffanys Notizbuch findet Ihr Hinweise darauf, wo die einzelnen Teile zu finden sind.", progress = "Dazu müsst Ihr die ganze Welt bereisen. Ich hoffe, Ihr seid bereit, diese Herausforderung anzunehmen.", completion = "<Tiffany hält das Kistchen hoch und erklärt, wie sie es repariert hat.>\n\nJetzt solltet Ihr Euch problemlos ein eigenes Kistchen bauen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[40559] = { id = 40559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehr: Die Weisheit des Raben", description = "{name}, unser Freund hier hat mir viel über die Rabenwehr erzählt, zum Beispiel über einen Raum, der unzählige Bücher zu allen möglichen Handwerkstechniken beherbergt.\n\nIch wette, dass darunter auch ein Buch ist, das unserer Juwelierskunst dienlich sein könnte.\n\nGeht dort hin und bringt mir alles mit, was nützlich sein könnte. Ich werde eine schöne neue Vorlage mit Euch teilen, wenn Ihr zurück seid.", sourceObjective = "Geht zur Rabenwehr, findet ein Buch über Juwelierskunst und bringt es Jonas Timotheus in Dalaran.", progress = "Es gibt doch Nichts, was erbaulicher wäre, als ein gutes Buch!", completion = "<Timotheus blättert durch die Seiten>\n\nWas für ein glücklicher Fund, {name}. Da habt Ihr wirklich gute Arbeit geleistet.\n\nHier habt Ihr wie versprochen die neue Vorlage, von der ich sprach.", sourceObjectiveStatus = "unverified-source-field" }
quests[40560] = { id = 40560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Einmal Tod und zurück", description = "Ich muss Euch einen wirklich schweren Auftrag zumuten, {name}.\n\nIch möchte nämlich, dass Ihr sterbt. Aber Ihr dürft natürlich wiederauferstehen! \n\nEs gibt da ein Schiff, die Naglfar, das Seelen aus dieser in die nächste Welt transportiert. Man sagt, dass tief im Innern des Schiffes ein uralter Schatz verborgen liegt: der Ring der Gefallenen.\n\nIhr kennt mich, {name}. Es gibt Nichts, was mich mehr interessiert als ein außergewöhnlich hübscher Ring.\n\nFindet einen Weg, auf dieses Schiff zu kommen, und bringt mir diesen uralten Schatz zurück.", sourceObjective = "Begebt Euch zum Seelenschlund und bringt den Ring der Gefallenen zu Jonas Timotheus in Dalaran.", progress = "Die Göttin, die diese Welt beherrscht, wird Euch ohne einen Kampf nicht gehen lassen. Passt auf Euch auf, {name}.", completion = "Ihr habt ihn gefunden?! Und Ihr habt es zurück geschafft!\n\n{name}, nur für diese Gelegenheit und nur für Euch habe ich mir ein paar Worte zurechtgelegt.\n\n\"{name} verspürt die Schmerzen nicht, lacht selbst dem Tode ins Gesicht und bezwingt sogar das Jüngste Gericht!\"", sourceObjectiveStatus = "unverified-source-field" }
quests[40561] = { id = 40561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Himmlische Klunker", description = "Königinnen und Könige tragen traditionellerweise die schönsten Ringe! Und ich hörte, dass ein gewisser König der Götter uns mit seiner Anwesenheit ehrt.\n\nIn den Hallen der Tapferkeit verwahrt Odyn unermessliche Schätze. Wenn Ihr also vorhabt, dort vorbeizuschauen, könntet Ihr mir vielleicht einen seiner Ringe... mitbringen.\n\nEr wird ihn wahrscheinlich nicht freiwillig herausrücken, also macht Euch auf den Kampf Eures Lebens gefasst.", sourceObjective = "Tötet Odyn in den Hallen der Tapferkeit und bringt seinen Ring zu Jonas Timotheus in Dalaran.", progress = "Das ist definitiv das schönste Stück in meiner Sammlung.", completion = "Was für ein prachtvoller Ring! Wie wundervoll es wäre, an der Seite der Juwelierschleifer im Himmel zu arbeiten.\n\nEin solch wertvoller Fund verlangt nach einer angemessenen Belohnung. Hier ist eine meiner neuesten Ringvorlagen. Ich hoffe, dass sie Euch von Nutzen sein wird, {name}.", sourceObjectiveStatus = "unverified-source-field" }
